def transform(grid):
    out = [row[:] for row in grid]
    occupied = [i for i, row in enumerate(grid) if 4 in row]
    top, bottom = min(occupied), max(occupied)
    for dest, src in enumerate(range(bottom, top - 1, -1), start=bottom + 1):
        if dest < len(out):
            out[dest] = [4 if value == 4 else 0 for value in grid[src]]
    return out
